// --- Class index of the largest logit -------------------------------------
// Returns int, not elem_t. The deployment scaffolding's utils_refact.c
// declares `elem_t argmax(int, elem_t *)`, which silently wraps any index
// >= 128 into a negative number -- invisible on a 10- or 100-class model,
// fatal on ImageNet's 1000, where it caps measured top-1 at the fraction of
// labels below 128. Emitting our own keeps the generated file independent of
// that signature.
static int vit_argmax(int size, const elem_t * input) {
    int best = 0;
    for (int i = 1; i < size; i++) {
        if (input[i] > input[best]) best = i;
    }
    return best;
}

// --- Transformer kernel scratch (shared, sized to the largest user) ---
static acc_t vit_softmax_scratch[65];

// ==========================================
// Transformer integer kernels (emitted by src/codegen)
// ==========================================
// I-BERT integer-only formulation, matching Gemmini's own apply_iexp/IGELU.
// Define GEMMINI_NATIVE_NORM to route LayerNorm through the accelerator's
// normalization unit instead (requires a HAS_NORMALIZATIONS Gemmini config).

#ifndef VIT_KERNELS_EMITTED
#define VIT_KERNELS_EMITTED

static inline int vit_round_sat(float x) {
    float y = x < 0.0f ? x - 0.5f : x + 0.5f;
    int i = (int)y;
    if (i > elem_t_max) i = elem_t_max;
    if (i < elem_t_min) i = elem_t_min;
    return i;
}

// --- libm-free math -------------------------------------------------------
// Bare-metal Gemmini/Pelletron builds do not necessarily link libm, so these
// kernels must not reference sqrt()/expf(). Both are computed directly.

// Newton-refined inverse square root, then x * (1/sqrt(x)).
static inline float vit_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    union { float f; uint32_t i; } u;
    u.f = x;
    u.i = 0x5f3759dfu - (u.i >> 1);
    float r = u.f;
    r = r * (1.5f - 0.5f * x * r * r);
    r = r * (1.5f - 0.5f * x * r * r);
    r = r * (1.5f - 0.5f * x * r * r);
    return x * r;
}

// Pade [7/8] approximation of tanh: ~1e-7 accurate on |x| < 4, saturating
// beyond. Preferred over a Schraudolph exp-based tanh (few-percent error),
// since GELU's output feeds straight into the next quantized matmul.
static inline float vit_tanhf(float x) {
    float ax = x < 0.0f ? -x : x;
    if (ax > 8.0f) return x < 0.0f ? -1.0f : 1.0f;
    float x2 = x * x;
    float num = x * (135135.0f + x2 * (17325.0f + x2 * (378.0f + x2)));
    float den = 135135.0f + x2 * (62370.0f + x2 * (3150.0f + 28.0f * x2));
    float t = num / den;
    if (t > 1.0f) t = 1.0f;
    if (t < -1.0f) t = -1.0f;
    return t;
}

// --- Integer square root, for LayerNorm's stddev ---------------------------
// Newton on integers, seeded from a power of two above the root. ~5 iterations
// for anything under 2^62; called once per row, so its cost is amortized over
// `cols` elements.
static inline long long vit_isqrt(long long x) {
    if (x <= 0) return 0;
    long long g = 1;
    while (g < (long long)3037000499LL && g * g < x) g <<= 1;
    for (int k = 0; k < 12; k++) {
        long long next = (g + x / g) >> 1;
        if (next >= g) break;
        g = next;
    }
    return g;
}

// --- LayerNorm (affine-free), requantizing to scale_out ---------------------
// LayerNorm is scale-invariant, so the input scale cancels and only the output
// scale is needed. The accelerator cannot take this op over -- see the note on
// vit_accel_norm(LAYERNORM) in VIT_ACCEL_C -- so the kernel is the only lever.
//
// Two passes, integer throughout, from the identity
//
//     (x - mean)/stddev == (n*x - S1) / sqrt(n*S2 - S1^2)
//
// with S1 = sum(x), S2 = sum(x^2), n = cols. Both sides are exact in integers
// (verified in rationals for n = 65, 144, 768), which matters twice over:
//
//   * S1 and S2 come from ONE pass. The textbook form needs two -- one for the
//     mean, one for the deviations -- and on this target the kernel is bound
//     by instructions retired, so a whole pass over the row is ~5 of the ~18
//     instructions per element.
//   * there is no cancellation to worry about. `n*S2 - S1^2` is the usual
//     numerically-dangerous variance shortcut only in floating point; over
//     integers it is exact, and Cauchy-Schwarz makes it non-negative.
//
// The final divide becomes a Q16 multiply-shift with the whole row's constants
// folded in: out = (x*A - B) >> 16, one multiply and one subtract per element.
//
// Widths: n*S2 and S1^2 reach 9.5e9 at cols=768, so the statistics are int64.
// x*A stays well inside int32 for realistic scales but is computed in int64
// anyway -- on RV64 the wider multiply is the same one instruction.
//
// Measured on minivit/cifar10/small, n=32, Softmax and GELU on the
// accelerator, over 13 LayerNorms:
//
//     double, three passes      96,360,568 cycles   84.4% top-1
//     integer Q3, three passes 104,322,795 cycles   84.4% top-1
//     integer, two passes       (this)              (see README)
//
// The middle row is why the double version is not simply "the slow one": this
// target builds with -march=rv64gc, whose `d` is hardware double precision, so
// there are no soft-float calls to eliminate. Only removing a pass helps.
#ifdef VIT_FLOAT_LAYERNORM

// The textbook formulation, kept as an A/B reference. Three passes and
// hardware double precision; correct, and measurably slower -- see the
// numbers above. Requires an FPU, which the integer kernel does not.
static void vit_layernorm(int rows, int cols,
                          const elem_t * in, int in_row_stride,
                          elem_t * out, int out_row_stride,
                          float scale_out) {
    for (int r = 0; r < rows; r++) {
        const elem_t * src = in + (size_t)r * in_row_stride;
        elem_t * dst = out + (size_t)r * out_row_stride;

        acc_t sum = 0;
        for (int c = 0; c < cols; c++) sum += (acc_t)src[c];
        double mean = (double)sum / (double)cols;

        double var_acc = 0.0;
        for (int c = 0; c < cols; c++) {
            double d = (double)src[c] - mean;
            var_acc += d * d;
        }
        double stddev = (double)vit_sqrtf((float)(var_acc / (double)cols) + 1e-5f);
        if (stddev <= 0.0) stddev = 1.0;

        double inv = 1.0 / (stddev * (double)scale_out);
        for (int c = 0; c < cols; c++) {
            dst[c] = (elem_t)vit_round_sat((float)(((double)src[c] - mean) * inv));
        }
    }
}

#else

static void vit_layernorm(int rows, int cols,
                          const elem_t * in, int in_row_stride,
                          elem_t * out, int out_row_stride,
                          float scale_out) {
    const long long n = cols;

    for (int r = 0; r < rows; r++) {
        const elem_t * src = in + (size_t)r * in_row_stride;
        elem_t * dst = out + (size_t)r * out_row_stride;

        long long s1 = 0, s2 = 0;
        for (int c = 0; c < cols; c++) {
            const long long v = (long long)src[c];
            s1 += v;
            s2 += v * v;
        }

        // n*stddev, exactly. Floored at n (stddev = 1) so a constant row
        // cannot blow up the multiplier; this also stands in for the usual
        // epsilon under the square root.
        long long d = vit_isqrt(n * s2 - s1 * s1);
        if (d < n) d = n;

        // The row's whole affine map folds into A and B, plus the rounding
        // bias into B, so an element costs one multiply, one subtract, one
        // shift and the clamp:
        //
        //     out = (x*A - B) >> 16,   A = n*65536/(d*scale_out)
        //                              B = s1*65536/(d*scale_out) - 32768
        //
        // Note `n` is folded into the *float* reciprocal rather than applied
        // as `n * mult` afterwards. Arithmetically identical, but with a
        // literal n in scope gcc re-associates x*(n*mult) into (x*mult)*n and
        // expands the constant multiply into slli/add/slli -- three extra
        // instructions in the hot loop. Deriving A from a float conversion
        // leaves it opaque, and the loop keeps its single `mul`.
        //
        // Rounding is a plain +0.5 rather than round-half-away-from-zero: the
        // sign-dependent form costs three more instructions (gcc emits
        // srai/and/add to keep it branchless) to move negative halves by one
        // output LSB, which the clamp below is coarser than anyway.
        const float inv = 65536.0f / ((float)d * scale_out);
        // Rounded, not truncated: a cast truncates toward zero, which biases
        // A low and compresses the row's output by a fraction of an LSB.
        const float fa = (float)n * inv, fb = (float)s1 * inv;
        const long long A = (long long)(fa + 0.5f);
        const long long B = (long long)(fb + (fb >= 0.0f ? 0.5f : -0.5f)) - 32768;

        for (int c = 0; c < cols; c++) {
            // Kept in long long the whole way: mixing widths made gcc emit a
            // sext.w before each comparison.
            long long v = ((long long)src[c] * A - B) >> 16;
            if (v > elem_t_max) v = elem_t_max;
            else if (v < elem_t_min) v = elem_t_min;
            dst[c] = (elem_t)v;
        }
    }
}

#endif // VIT_FLOAT_LAYERNORM

// --- I-BERT integer-only Softmax -------------------------------------------
// exp(x) = exp(p) >> z with x = -ln2*z + p, and exp(p) approximated by
// L(p) = a(p+b)^2 + c on p in (-ln2, 0]. `scale_in` is the real-value-per-LSB
// of the input logits; rows are normalized to [0, elem_t_max] like Gemmini's
// fused SOFTMAX, so downstream consumers must divide by elem_t_max.
static void vit_isoftmax(int rows, int cols,
                         const elem_t * in, int in_row_stride,
                         elem_t * out, int out_row_stride,
                         float scale_in) {
    const float a = 0.3585f, b = 1.353f, c = 0.344f;
    const acc_t qln2     = (acc_t)(0.6931472f / scale_in);
    const acc_t qln2_inv = qln2 > 0 ? (acc_t)(65536 / qln2) : 1;
    const acc_t qb       = (acc_t)(b / scale_in);
    const acc_t qc       = (acc_t)(c / (a * scale_in * scale_in));

    for (int r = 0; r < rows; r++) {
        const elem_t * src = in + (size_t)r * in_row_stride;
        elem_t * dst = out + (size_t)r * out_row_stride;

        acc_t max_q = src[0];
        for (int j = 1; j < cols; j++) if (src[j] > max_q) max_q = src[j];

        acc_t sum_exp = 0;
        for (int j = 0; j < cols; j++) {
            // q <= 0 guarantees z >= 0, which the shift below requires.
            acc_t q = (acc_t)src[j] - max_q;
            acc_t z = (acc_t)((-q * qln2_inv) >> 16);
            acc_t qp = q + z * qln2;
            acc_t q_exp = (qp + qb) * (qp + qb) + qc;
            if (q_exp < 0) q_exp = 0;
            q_exp >>= z;
            ((acc_t*)vit_softmax_scratch)[j] = q_exp;
            sum_exp += q_exp;
        }
        if (sum_exp == 0) sum_exp = 1;

        for (int j = 0; j < cols; j++) {
            acc_t num = ((acc_t*)vit_softmax_scratch)[j] * (acc_t)elem_t_max
                      + (sum_exp >> 1);
            acc_t v = num / sum_exp;
            if (v > elem_t_max) v = elem_t_max;
            if (v < 0) v = 0;
            dst[j] = (elem_t)v;
        }
    }
}

// --- GELU (tanh approximation), requantizing scale_in -> scale_out ----------
static void vit_gelu(int count, const elem_t * in, elem_t * out,
                     float scale_in, float scale_out) {
    const float k0 = 0.7978845608f;   // sqrt(2/pi)
    const float k1 = 0.044715f;
    const float inv_out = 1.0f / scale_out;
    for (int i = 0; i < count; i++) {
        float x = (float)in[i] * scale_in;
        float inner = k0 * (x + k1 * x * x * x);
        out[i] = (elem_t)vit_round_sat(0.5f * x * (1.0f + vit_tanhf(inner)) * inv_out);
    }
}

#endif // VIT_KERNELS_EMITTED


